function removeDuplicates(s) {
  // Delete the first adjacent equal pair found, then rescan from the start, until no pair is left.
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + 1 < s.length; i++) {
      if (s[i] === s[i + 1]) {
        s = s.slice(0, i) + s.slice(i + 2);
        changed = true;
        break;
      }
    }
  }
  return s;
}

