function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  // A small alphabet makes equal neighbours, and so chains of removals, common.
  const letters = 2 + Math.floor(rand() * (size === 'large' ? 3 : 4));
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [s];
}
